      setInstitutions((items) => mode === "edit" ? items.map((item) => item.code === id ? next : item) : [...items,next]); recordAudit(mode === "edit" ? "institution.update" : "institution.create",mode === "edit" ? "INSTITUTION_UPDATE" : "INSTITUTION_CREATE",next.id,"SUCCESS",next.name);
