      const noKey = dataset.businessKeyCount === 0; const hasIncrement = Boolean(dataset.incrementalField); const scheduleMode = str(values,"scheduleMode") as TaskVersion["scheduleMode"]; const interval = scheduleMode === "EVERY_N_HOURS" ? Number(str(values,"scheduleIntervalHours")) : null; const cron = scheduleMode === "CRON" ? str(values,"scheduleCron") : scheduleMode === "EVERY_N_HOURS" ? staggeredCron(institution.code,dataset.code,interval ?? 1) : null;
