    const fieldRows = selected ? [["ORG_CODE","医疗机构代码","AN..64","NOT NULL","机构范围"],...(selected.businessKeyCount ? Array.from({length:selected.businessKeyCount},(_,index) => [`BUSINESS_KEY_${index + 1}`,`业务主键字段 ${index + 1}`,"AN..128","NOT NULL",`KEY ${index + 1}`]) : []),...(selected.incrementalField ? [[selected.incrementalField,"增量时间字段","DT","NOT NULL","INCREMENTAL"]] : []),["…",`其余 ${Math.max(0,selected.fieldCount - selected.businessKeyCount - (selected.incrementalField ? 2 : 1))} 个标准字段`,"按合同","按合同","只读"]] : [];
